"""Builds public/data/areas.js from archive/areas/areas_*.py (lists named AREAS)."""
import json, glob, os, runpy
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
areas, seen = [], set()
for f in sorted(glob.glob(os.path.join(ROOT, 'archive', 'areas', 'areas_*.py'))):
    for a in runpy.run_path(f)['AREAS']:
        assert a['id'] not in seen, a['id']; seen.add(a['id'])
        for k in ('id', 'name', 'kind', 'lat', 'lon', 'summary'): assert a.get(k) not in (None, ''), (a['id'], k)
        a = {k: v for k, v in a.items() if v not in (None, '', [])}
        areas.append(a)
# researched landmark batches (archive/areas/landmarks_batch_*.json): need coordinates inside Greater Tripoli; skip duplicates
import re
norm = lambda t: re.sub(r'[^a-z0-9\u0600-\u06ff]+', '', (t or '').lower())
names = {norm(n) for a in areas for n in [a['name']] + a.get('aliases', [])}
skipped = []
nocoord = []
batch = []
for f in sorted(glob.glob(os.path.join(ROOT, 'archive', 'areas', 'landmarks_batch_*.json'))): batch += json.load(open(f))
batch.sort(key=lambda a: -sum(len(str(a.get(k) or '')) for k in ('summary', 'history', 'era', 'today')))  # keep the richest profile of any duplicates
if True:
    for a in batch:
        key = norm(a.get('name'))
        if re.search(r'bab.?al.?azi[sz]ia', a.get('name', '').lower()): skipped.append((a.get('name'), 'location conflicts with the existing site')); continue
        if a.get('id') in seen or key in names: skipped.append((a.get('name'), 'duplicate')); continue
        lat, lon = a.get('lat'), a.get('lon')
        if not (isinstance(lat, (int, float)) and isinstance(lon, (int, float)) and 32.0 <= lat <= 33.4 and 12.2 <= lon <= 14.3): skipped.append((a.get('name'), 'no coordinates')); nocoord.append(a); continue
        if not a.get('summary'): skipped.append((a.get('name'), 'no summary')); continue
        a = {k: v for k, v in a.items() if v not in (None, '', []) and k not in ('category', 'built', 'period')}
        a['kind'] = a.get('kind') if a.get('kind') in ('landmark', 'government', 'prison', 'military') else 'landmark'
        toks = {w for w in re.findall(r'[a-z]{4,}', a['name'].lower()) if w not in ('tripoli', 'libya', 'libyan', 'hotel', 'mosque', 'ministry', 'hospital', 'international', 'national', 'cemetery', 'center', 'centre', 'university', 'library', 'office', 'headquarters', 'stadium', 'square', 'museum', 'court', 'airport', 'building', 'italian', 'jewish', 'british', 'embassy', 'palace', 'castle')} | {w for w in re.findall(r'[a-z]{4,}', a['name'].lower()) if w in ('castle', 'cathedral', 'palace', 'cemetery', 'embassy', 'stadium') and False}
        near = [b for b in areas if abs(b['lat'] - lat) < 0.0013 and abs(b['lon'] - lon) < 0.0015 and (toks & set(re.findall(r'[a-z]{4,}', b['name'].lower() + ' ' + ' '.join(b.get('aliases', [])).lower())) or abs(b['lat'] - lat) < 0.0002 and abs(b['lon'] - lon) < 0.0002)]
        if near: skipped.append((a.get('name'), 'duplicate of ' + near[0]['id'])); continue
        seen.add(a['id']); names.add(key); areas.append(a)
more = [{'name': a['name'], 'when': (a.get('built') or ''), 'text': ' '.join(x for x in [a.get('summary'), a.get('history'), a.get('era'), a.get('today'), a.get('uncertain')] if x), 'src': (a.get('sources') or [None])[0] and {'t': a['sources'][0].get('t'), 'u': a['sources'][0].get('u')}} for a in nocoord if a.get('summary')]
open(os.path.join(ROOT, 'public', 'data', 'unplaced.js'), 'w').write('/* Generated by scripts/build-areas.py: researched places with no published coordinates. */\nwindow.ATLAS_UNPLACED_MORE = ' + json.dumps(more, ensure_ascii=False) + ';\n')
print(len(more), 'profiles without coordinates')
if skipped: print('skipped', len(skipped), skipped[:40])
json.dump(areas, open(os.path.join(ROOT, 'archive', 'areas', 'areas.json'), 'w'), ensure_ascii=False, indent=1)
with open(os.path.join(ROOT, 'public', 'data', 'areas.js'), 'w') as fh:
    fh.write('/* Generated by scripts/build-areas.py from archive/areas/. Profiles of Tripoli neighbourhoods, military sites and landmarks. */\nwindow.ATLAS_AREAS = ' + json.dumps(areas, ensure_ascii=False) + ';\n')
print(len(areas), 'areas', {k: sum(1 for a in areas if a['kind'] == k) for k in set(a['kind'] for a in areas)})
